// Последний обход. Здесь находятся правила загадки, а не скрытый жанровый preset.
// Упражнение: в escape разрешите выход без записи или измените реакцию mirror.
const component = {
  name: "HauntedRoom",
  parameters: { type: "object", properties: {
    requireRecord: { type: "boolean", default: true, label: "Для выхода нужна запись смены" },
  } },
  state: { type: "object", properties: {
    fuse: { type: "boolean", default: false, label: "Предохранитель найден" },
    power: { type: "boolean", default: false, label: "Питание включено" },
    record: { type: "boolean", default: false, label: "Запись прослушана" },
    mirrorSeen: { type: "boolean", default: false, label: "Отражение замечено" },
    escaped: { type: "boolean", default: false, label: "Обход завершён" },
    objective: { type: "string", default: "Найдите предохранитель на столе у входа.", label: "Текущая задача" },
  } },
  references: { type: "object", properties: {
    shadow: { type: "reference", referenceType: "object", label: "Чужой силуэт" },
    lamp: { type: "reference", referenceType: "object", label: "Аварийный свет" },
    exit: { type: "reference", referenceType: "mechanic", label: "Замок выхода · LockedDoor" },
    ending: { type: "reference", referenceType: "beat", label: "Финал истории" },
  } },
  signals: { changed: { name: "Обход изменился", payloadSchema: { type: "object", properties: { stage: { type: "string" } } } } },
  lifecycle: { initialize: "prepare" },
  methods: {
    prepare: { name: "Подготовить новый обход", async run({ refs, engine }) {
      await engine.operation("sacura.object.visible", { object: refs.shadow, visible: false });
      await engine.operation("sacura.object.visible", { object: refs.lamp, visible: false });
      await engine.operation("sacura.camera.look", { delta: [0, 40], device: "pointer" });
    } },
    takeFuse: { name: "Взять предохранитель", result: { type: "boolean" }, async run({ state, engine }) {
      if (state.fuse) return false;
      state.fuse = true;
      state.objective = "Установите предохранитель в красный щит у дальней стены.";
      await engine.operation("sacura.game.message", { message: "Керамика ещё тёплая. Кто-то вынул предохранитель перед вашим приходом." });
      await engine.emit("changed", { stage: "fuse" });
      return true;
    } },
    power: { name: "Восстановить питание", result: { type: "boolean" }, async run({ state, refs, engine }) {
      if (!state.fuse) { await engine.operation("sacura.game.message", { message: "Пустое гнездо. Нужен предохранитель со стола смотрителя." }); return false; }
      if (state.power) { await engine.operation("sacura.game.message", { message: "Щит гудит. Теперь работает магнитофон." }); return true; }
      state.power = true;
      state.objective = "Прослушайте магнитофон на синем столе. Не оборачивайтесь на стук.";
      await engine.operation("sacura.object.visible", { object: refs.lamp, visible: true });
      await engine.operation("sacura.object.visible", { object: refs.shadow, visible: true });
      await engine.operation("sacura.game.message", { message: "Свет вспыхнул. В конце коридора стоит человек в вашей форме. У него нет лица." });
      await engine.emit("changed", { stage: "power" });
      return true;
    } },
    listen: { name: "Прослушать запись", result: { type: "boolean" }, async run({ state, refs, engine }) {
      if (!state.power) { await engine.operation("sacura.game.message", { message: "Катушки неподвижны. Сначала восстановите питание щита." }); return false; }
      state.record = true;
      state.objective = "Выход разблокирован. Вернитесь к зелёной двери и завершите обход.";
      await engine.invoke(refs.exit, "setLocked", { value: false });
      await engine.operation("sacura.object.visible", { object: refs.shadow, visible: false });
      await engine.operation("sacura.game.message", { message: "Ваш голос на ленте: «Смена закончилась тридцать лет назад. Не отвечай, если назовут по имени». Замок выхода щёлкнул." });
      await engine.emit("changed", { stage: "record" });
      return true;
    } },
    mirror: { name: "Посмотреть в зеркало", async run({ state, refs, engine }) {
      state.mirrorSeen = !state.mirrorSeen;
      await engine.operation("sacura.object.visible", { object: refs.shadow, visible: state.mirrorSeen });
      await engine.operation("sacura.game.message", { message: state.mirrorSeen ? "В зеркале вы всё ещё стоите у входа. Отражение поднимает руку, хотя вы не двигались." : "Отражение исчезло. На стекле изнутри проступило: «Не оставайся на вторую смену»." });
    } },
    escape: { name: "Завершить обход", result: { type: "boolean" }, async run({ params, state, refs, engine }) {
      if (state.escaped) return true;
      if (!state.power || (params.requireRecord && !state.record)) {
        await engine.operation("sacura.game.message", { message: "Заперто. В журнале сказано: восстановить питание и прослушать последнюю запись." }); return false;
      }
      await engine.invoke(refs.exit, "setLocked", { value: false });
      await engine.invoke(refs.exit, "open", {});
      state.escaped = true;
      state.objective = "Вы выбрались. Сегодня в журнале впервые появилась новая дата.";
      await engine.emit("changed", { stage: "escaped" });
      await engine.operation("sacura.story.enter", { beat: refs.ending });
      return true;
    } },
  },
};

// Один исходник для всех осматриваемых предметов. Владелец, текст и ссылки — у экземпляра.
// Измените порог distance или добавьте реакцию в ветку kind — это реальное поведение.
const component = {
  name: "HauntedProp",
  parameters: { type: "object", properties: {
    kind: { type: "string", enum: ["examine", "fuse", "power", "tape", "mirror", "exit"], options: { examine: "Осмотреть", fuse: "Взять предохранитель", power: "Включить питание", tape: "Прослушать запись", mirror: "Заглянуть в зеркало", exit: "Выйти" }, default: "examine", label: "Действие предмета" },
    text: { type: "string", default: "Здесь кто-то был.", label: "Текст осмотра" },
    distance: { type: "number", min: 1, default: 3.2, label: "Расстояние взаимодействия" },
  } },
  state: { type: "object", properties: { visits: { type: "integer", default: 0, label: "Осмотров" }, taken: { type: "boolean", default: false, label: "Подобран" } } },
  references: { type: "object", properties: {
    room: { type: "reference", referenceType: "mechanic", label: "Правила обхода · HauntedRoom" },
    viewer: { type: "reference", referenceType: "object", label: "Кто осматривает" },
  } },
  methods: { interact: { name: "Осмотреть / использовать", result: { type: "boolean" }, async run({ params, state, refs, owner, engine }) {
    const seen = await engine.operation("sacura.spatial.observe", { owner, target: refs.viewer });
    if (!seen.available || seen.distance > params.distance) {
      await engine.operation("sacura.game.message", { message: "Подойдите ближе: WASD. Зажмите правую кнопку мыши, чтобы осмотреться." }); return false;
    }
    state.visits += 1;
    if (params.kind === "fuse") {
      if (state.taken) return false;
      if (await engine.invoke(refs.room, "takeFuse", {})) {
        state.taken = true;
        await engine.operation("sacura.object.visible", { object: owner, visible: false });
      }
    } else if (params.kind === "power") return await engine.invoke(refs.room, "power", {});
    else if (params.kind === "tape") return await engine.invoke(refs.room, "listen", {});
    else if (params.kind === "mirror") await engine.invoke(refs.room, "mirror", {});
    else if (params.kind === "exit") return await engine.invoke(refs.room, "escape", {});
    else await engine.operation("sacura.game.message", { message: params.text });
    return true;
  } } },
};

// Два подключения используют один исходник. Условия меняются здесь.
// Упражнение: вместо count > 0 потребуйте count >= 2 или добавьте вызов Reward.award.
// SetLocked(false) меняет только замок. Open — отдельная ожидаемая анимация.
const component = {
  name: "LockedDoor",
  parameters: {
    type: "object",
    properties: {
      InitiallyLocked: { type: "boolean", default: true, label: "Изначально заперта · IsLocked" },
      requiresKey: { type: "boolean", default: false, label: "Разрешать открытие ключом" },
      consumeKey: { type: "boolean", default: false, label: "Расходовать ключ" },
      OpenSeconds: { type: "number", min: 0, default: 0.5, label: "Время открытия, сек" },
    },
  },
  state: {
    type: "object",
    properties: { IsLocked: { type: "boolean", default: true, label: "Заперта · IsLocked" } },
  },
  stateFromParameters: { IsLocked: "InitiallyLocked" },
  references: {
    type: "object",
    properties: {
      inventory: {
        type: "union",
        optional: true,
        label: "Инвентарь",
        variants: [
          { type: "reference", referenceType: "object", label: "Инвентарь объекта" },
          { type: "reference", referenceType: "project", label: "Инвентарь проекта" },
        ],
      },
      key: { type: "reference", referenceType: "item", optional: true, label: "Нужный ключ" },
    },
  },
  signals: { opened: { name: "Дверь открыта", payloadSchema: { type: "object", properties: {} } } },
  methods: {
    setLocked: {
      name: "Задать замок",
      parameters: {
        type: "object",
        properties: { value: { type: "boolean", default: false, label: "Заперта" } },
      },
      result: { type: "boolean" },
      run({ args, state }) {
        state.IsLocked = args.value;
        return state.IsLocked;
      },
    },
    canUnlock: {
      name: "Проверить ключ",
      result: { type: "boolean" },
      async run({ params, refs, engine }) {
        if (!params.requiresKey || !refs.inventory || !refs.key) return false;
        const count = await engine.operation("sacura.inventory.count", {
          owner: refs.inventory,
          item: refs.key,
        });
        return count > 0;
      },
    },
    interact: {
      name: "Взаимодействовать",
      result: { type: "boolean" },
      async run({ state, params, refs, engine, self }) {
        if (state.IsLocked) {
          if (!(await engine.invoke(self, "canUnlock", {}))) {
            await engine.operation("sacura.game.message", { message: "Заперто" });
            return false;
          }
          if (params.consumeKey)
            await engine.operation("sacura.inventory.remove", {
              owner: refs.inventory,
              item: refs.key,
              count: 1,
            });
          await engine.invoke(self, "setLocked", { value: false });
        }
        return await engine.invoke(self, "open", {});
      },
    },
    open: {
      name: "Открыть",
      result: { type: "boolean" },
      async run({ engine, owner, params }) {
        await engine.operation("sacura.door.animate", {
          object: owner,
          open: true,
          seconds: params.OpenSeconds,
        });
        await engine.emit("opened", {});
        return true;
      },
    },
  },
};
